INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2390, 'ruRU', 'Судьба Джозефа Рэдпата Джозеф Рэдпат был убит во время битвы при Дарроушире. Его дух был порчен и принял новую форму, и это существо несло великое зло по Лордерону. У Иссохшей обители Гаррона, к востоку от Андорала, порченный Рэдпат был наконец побеждён силами Альянса. Его щит до сих пор лежит рядом с сараем заражённой чумой усадьбы, и прислужники Плети до сих пор притягиваются к памяти о его зле.', 0),
(2410, 'ruRU', 'Судьба Карлина Рэдпата Брат капитана Джозефа Рэдпата, Карлин погиб во время битвы при Дарроушире. Но, несмотря на страшные раны, он не был убит. Спустя несколько дней после битвы агенты Серебряного Авангарда нашли Карлина, бродящего, слабого от жажды и лихорадки, возле Переправы Корина. Они залечили его раны и привели его в часовню Последней Надежды. Благодарный за их милосердие, Карлин присоединился к рядам Серебряного Авангарда и теперь ведёт битву за отмщение против Плети.', 0),
(2412, 'ruRU', 'OoOoOoO OOoOOoo OOOoOoo OOoOooO OOoOOoO OOooooO Oooooo OooOOOO OOoOOOo OOoOOoo OOoOooO OOoOOOo OOooOoO Oooooo OooOOOo OOooooO OOOoooo OOooooO Oooooo OoOoOOo OOooooO OOoOOoo OOoOOoo OOooOoO OOOOooO Oooooo OooOoOO OOoOOOo OOoOooO OOooOOO OOoOooo OOOoOoo OOOooOO Oooooo OOoOOOO OOooOOo Oooooo OooooOO OOoOooo OOooooO OOoOOOO OOOooOO', 0),
(2490, 'ruRU', 'Надеюсь, эта печать найдёт тебя в добром здравии, $N. Духи рассказали мне о твоём прибытии, и я сразу отправила весть. Я с нетерпением жду возможности поделиться своим опытом с тобой и помочь направить тебя, когда ты будешь готов покинуть Тельдрассил для более важных дел.$B$BПри всём, что произошло за последние несколько лет, мы можем многое сделать, чтобы помочь другим расам Азерота. Когда будешь готов, найди меня внутри Альдрассила, на втором уровне.$B$B-Шанда, наставник жрецов', 0),
(2510, 'ruRU', 'Гриш-$B$BТвоя просьба об отпуске принята. Я отправляю резервного таурена-воина охранять твой пост, пока ты проводишь время с семьёй. Доложи о прибытии через неделю!$B$B-Магран Землепряд', 0),
(2530, 'ruRU', 'По приказу Верховного палача Хадрека, ниже перечислены предметы, необходимые для поддержания запасов Усыпальницы: 12 длинных мечей 9 кинжалов 8 круглых щитов 15 топоров 1000 стрел Выполнение этого приказа следует считать прямым распоряжением Тёмной Госпожи, и виновные будут представлены Её вниманию, как и любой, кто противится или иным образом препятствует Её желаниям.', 0),
(2550, 'ruRU', 'Этот документ из 3 страниц пуст.', 0),
(2570, 'ruRU', 'Лайо:$B$BМы получили щедрую помощь этого прекрасного искателя приключений. Я направил искателя приключений к тебе в Силитус как ресурс. Пожалуйста, проследи, чтобы такой ценный ресурс не пропал зря в твоих стараниях раскрыть тайны, что там скрыты. Круг с нетерпением ждёт вестей о продвижении.$B$BПусть Кенарий хранит тебя...$BРабин', 0),
(2590, 'ruRU', 'Современное соблюдение$B$BДругие культуры начали признавать Пир Зимнего Покрова как время великого празднования, хотя и не в тех же традициях, на которых основана легенда. Обычаи, часто не связанные ни с чем, кроме возможности для празднования и обмена подарками, вошли в современное соблюдение этого времени года. Даже образ Дедушки Зимы иногда используется, но скорее как предвестник коммерческой выгоды, чем как сверхъестественный титан.', 0),
(2594, 'ruRU', 'В амулете не хватает пяти самоцветов. И если бы эти самоцветы были найдены и возвращены в символ, его сила значительно превысила бы текущую форму. Я нашёл пять самоцветов, но мне нужен кто-то с твоим мастерством, чтобы помочь собрать их. Убийство Безымянного Пророка — несомненно, ересь, как и кража с его трупа, но то, о чём я попрошу тебя дальше, осудил бы любой кентавр, даже за одну мысль об этом.', 0),
(2597, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nМолодой Воин не бойся этого нового,мистического места! ты будешь поражён чудесами которые увидишь! Много опасностей таится в тени, много разбойников готовы убить тебя за пятачок.... Так что берегись всего что опасно и прорубай себе дорогу к лучшей жизни!\n\n', 0),
(2598, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nТак, юный боец.Ты пытаешься стать Паладином?Ну хорошо... Помни будь храбрым, стой высоко и защищай невинных! И самое главное не забывай что есть Бог и ты его помощник....\n\n', 0),
(2599, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nХе-хе и ты называешь себя разбойником? Не смеши меня! Если хочешь стать настоящим разбойником покажи нам из чего ты сделан! А теперь иди грабь эти деревни!\n\n', 0),
(2600, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nСын мой чти Бога и ты спасёшься.... Чти Бога и спасёшься Чти Дьявола и станешь силён, но падёшь в Глазах Божьих! Так берегись дитя моё! БЕРЕГИСЬ!\n\n', 0),
(2601, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nМир — коварное место для нас шаманов, но всё же мы достаточно сильны чтобы выиграть эту заморочную битву... У нас есть всё что нужно чтобы убить этот надоедливый Альянс Теперь покажи мне из чего сделаны мы Шаманы!\n\n', 0),
(2602, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nМы Маги самые сильные пользователи Магии Мы сочетаем Огонь и Лёд чтобы получить максимальный эффект И мы поможем всему что в этом нуждается Так что иди и изучай магию исследования!\n\n', 0),
(2603, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nКолдун загадочный класс... Мы самые сильные когда дело доходит до использования магии Я знаю "маг самый сильный в заклинаниях бла бла бла..." Забудь это мы Колдуны произошли от Магов так что мы на самом деле сильнее....\n\n', 0),
(2604, 'ruRU', 'Добро пожаловать в мир Warcraft!\n\nНаше Племя пробудило твои силы дитя моё... Теперь ты Друид так называемый Гибрид.. Ты сочетаешь силу воина, разум Магов, Исцеляющую магию от Шаманов.... Мы уникальны ты должен всегда помогать своим друзьям, потому что мы Друиды это Высшая поддержка какую может получить гуманоид!\n\n', 0),
(2605, 'ruRU', 'Главные благодарности:\nСкриптеры заданий:\n==============================\nШульц. Теслеби. Остальная команда !rpg.\n\n', 0),
(2610, 'ruRU', 'Используй силу Амулета Духов, чтобы заставить их проявиться, и забери у них самоцветы! После этого помести самоцветы в Амулет Духов и верни его мне. Когда у меня будет Амулет Единения, я буду достаточно силён, чтобы объединить племена заново, чтобы мы наконец стали такими, какими нас хотели видеть наши предки!', 0),
(2630, 'ruRU', '... вот там ты и найдёшь легендарный меч Алого Верховного Лорда, Пеплосерд. Разве не удивительно, что можно найти в обычный день рыбалки?', 0),
(2637, 'ruRU', 'Компендиум Форора по убийству драконов — толстая книга, полная текста. К сожалению, текст выглядит бессвязным и не имеет для тебя смысла.', 0),
(2653, 'ruRU', '<Ты чувствуешь жгучую боль, бросив взгляд на эти страницы.>', 0),
(2660, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">РЯДОВОЙ СОСТАВ ОРДЫ</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Старший сержант</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Главный сержант</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Сержант</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Громила</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Разведчик</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2711, 'ruRU', 'Завершение ритуалаТы можешь следить за своим продвижением по магическим рунам вдоль границы круга. Когда появятся девять рун, ритуал будет завершён, и ты увидишь, как энергия поднимается из новообретшего силу Круга.Отсюда ты можешь воззвать к Ксоротийским письменам и открыть портал в Ксорот, чтобы вытянуть оттуда скакуна ужаса.Победи скакуна ужаса и освободи его дух. Противостой духу, и он будет порабощён, и ты будешь награждён секретом его призыва.', 12340),
(2770, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">ВОЕННЫЕ ЗВАНИЯ ОРДЫ</H1><BR/>\n<P align="center">ОФИЦЕРЫ</P><BR/>\n<P align="center">Верховный военный вождь</P>\n<P align="center">Военный вождь</P>\n<P align="center">Генерал</P>\n<P align="center">Генерал-лейтенант</P>\n<P align="center">Чемпион</P>\n<P align="center">Центурион</P>\n<P align="center">Легионер</P>\n<P align="center">Кровавая гвардия</P>\n<P align="center">Каменная гвардия</P><BR/>\n<P align="center">РЯДОВОЙ СОСТАВ</P><BR/>\n<P align="center">Старший сержант</P>\n<P align="center">Главный сержант</P>\n<P align="center">Сержант</P>\n<P align="center">Громила</P>\n<P align="center">Разведчик</P><BR/>\n</BODY>\n</HTML>\n', 0),
(2822, 'ruRU', 'Ты не можешь понять ни единого слова в этой бухгалтерской книге. Ты даже не знаешь, на каком языке она написана!', 0),
(2823, 'ruRU', 'Тысячи лет назад изгнанные Высокородные приплыли к берегам Лордерона и основали заколдованное королевство Кель''Талас. Эти высшие эльфы, как они себя называли, создали источник огромной магической энергии в самом сердце своей земли — Солнечный Колодец. С течением времени они всё больше зависели от неустойчивой энергии Колодца — несмотря на горькие уроки, усвоенные в прошлые эпохи.', 0),
(2824, 'ruRU', 'Во время Третьей войны злодей принц Артас вторгся в Кель''Талас и превратил некогда могучее королевство в руины и пепел. Его армия нежити уничтожила почти девяносто процентов населения высших эльфов. Кроме того, он использовал энергию Солнечного Колодца, чтобы воскресить Кел''тузада — могущественного лича-нежить — тем самым осквернив мистические воды Колодца. Немногие выжившие эльфы, осознав, что были отрезаны от источника своей магической силы, становились всё более нестабильными и отчаянными.', 0),
(2825, 'ruRU', 'В самый тёмный час эльфов явился Кель''тас Солнечный Скиталец — последний из королевской линии Кель''Таласа. Кель, как его обычно называли, знал, что остатки его народа не протянут долго без питающей магии, которая когда-то давала им силу. Переименовав свой народ в эльфов крови в честь павших соотечественников, он научил их использовать окружающую мистическую энергию — даже демоническую — чтобы утолить их страшную жажду магии.', 0),
(2826, 'ruRU', 'В поисках новой судьбы для своего народа — теперь называемого на эльфийском наречии Син''дорей — Кель''тас отправился в отдалённый мир Запределья, где встретил падшего ночного эльфа Иллидана. Под наставничеством Иллидана Кель и его эльфы крови вернули себе большую часть прежней силы.', 0),
(2827, 'ruRU', 'К сожалению, практика эльфов крови по использованию демонической энергии привела к тому, что их бывшие соратники по Альянсу стали их избегать. Так, оставшиеся на Азероте эльфы крови с надеждой смотрят на Орду, чтобы та помогла им добраться до Запределья, где они смогут объединиться с Кель''тасом и достичь золотой судьбы, которую он им обещал.', 0),
(2838, 'ruRU', 'Тому, кого это касается,\n\nКак я люблю эти игры, в которые мы играем.\n\nЯ могу лишь предположить, что если ты читаешь это письмо, то каким-то образом, через чудо или божественное провидение, тебе удалось одолеть меня. Немыслимо, я знаю, но в истории этого мира случались и более странные вещи.\n', 0),
(2839, 'ruRU', 'Как и во всём в жизни, в этой печальной истории есть славная, серебряная изнанка трагедии, хаоса и зла. Хоть ты и убил меня, ты сделал это так медленно и беспорядочно, что у меня было достаточно времени, чтобы написать это письмо ПОСЛЕ того, как я уничтожил твою единственную надежду спасти этот мир. Раздавленный красный кристаллический порошок — это всё, что осталось от осколка твоего скипетра.\n\n', 0),
(2840, 'ruRU', 'Наслаждайся доспехами Немезиды и Ярости бури, которые ты можешь найти в моей сокровищнице. Поверь мне, когда я говорю это: мне доставляет огромное удовольствие знать, что я сделал то, что не смог мой отец...\n\n\nС уважением,\n\nЛорд Виктор Неферий\n«Нефариан»\n', 0),
(2871, 'ruRU', '<HTML><BODY><H1 align="center">ЛОРД ВАЛТАЛАК, продолжение...</H1><BR/><P align="left">Разделив амулет на части, мы бежали от только что восставшего призрака Валталака, а также от его армии призрачных убийц. А шум, который мы устроили, сражаясь за амулет, поднял на ноги немалое число оставшихся защитников Шпиля!</P><BR/><P align="left">Почти все мы смогли выбраться из Чёрной горы и думали, что в безопасности. Но даже оттуда, из-за грани, Валталак посылал своих прислужников за нами, где бы мы ни прятались. Вскоре после той миссии Сокрытый Клинок распался, и тогда мы стали совсем лёгкой добычей.</P><BR/><P align="left">Как ты, должно быть, уже знаешь, это делает обиталище лорда Валталака, ныне покой Зверя в Шпиле Чёрной горы, последним из населённых призраками мест.</P><BR/></BODY></HTML>', 0),
(2875, 'ruRU', 'Missing WDB data.', 0),
(2898, 'ruRU', 'Missing WDB data.', 0),
(2904, 'ruRU', 'Предмет 1 из 1.', 12340),
(2915, 'ruRU', 'Предмет 3 из 4.', 12340);
